class Solution {
public:
    int punishmentNumber(int n) {
        auto can_partition = [](auto& self, const std::string& s, int start, int target) -> bool {
            if (start == (int)s.size()) return target == 0;
            int val = 0;
            for (int end = start; end < (int)s.size(); end++) {
                val = val * 10 + (s[end] - '0');
                if (val > target) break;
                if (self(self, s, end + 1, target - val)) return true;
            }
            return false;
        };
        int total = 0;
        for (int i = 1; i <= n; i++) {
            int sq = i * i;
            if (can_partition(can_partition, std::to_string(sq), 0, i)) {
                total += sq;
            }
        }
        return total;
    }
};

class Solution {
    public int punishmentNumber(int n) {
        int total = 0;
        for (int i = 1; i <= n; i++) {
            int sq = i * i;
            if (canPartition(Integer.toString(sq), 0, i)) {
                total += sq;
            }
        }
        return total;
    }

    private boolean canPartition(String s, int start, int target) {
        if (start == s.length()) return target == 0;
        int val = 0;
        for (int end = start; end < s.length(); end++) {
            val = val * 10 + (s.charAt(end) - '0');
            if (val > target) break;
            if (canPartition(s, end + 1, target - val)) return true;
        }
        return false;
    }
}

